export type MutationKey<TOptions extends Partial<Options>> = [
  Pick<TOptions, "baseUrl" | "body" | "headers" | "path" | "query"> & {
    _id: string;
    tags?: ReadonlyArray<string>;
  },
];

const createMutationKey = <TOptions extends Partial<Options>>(
  id: string,
  options?: TOptions,
  tags?: ReadonlyArray<string>,
): [MutationKey<TOptions>[0]] => {
  const params: MutationKey<TOptions>[0] = {
    _id: id,
    baseUrl: options?.baseUrl || (options?.client ?? client).getConfig().baseUrl,
  };
  if (tags) {
    params.tags = tags;
  }
  if (options?.body) {
    params.body = options.body;
  }
  if (options?.headers) {
    params.headers = options.headers;
  }
  if (options?.path) {
    params.path = options.path;
  }
  if (options?.query) {
    params.query = options.query;
  }
  return [params];
};

export const queryContractMutationKey = (options?: Partial<Options<QueryContractData>>) =>
  createMutationKey("queryContract", options);

/**
 * Call a read-only contract function on a direct peer
 *
 * Queries a contract index with a raw input type and hex payload against a direct peer. No ABI or contract name is assumed; the caller supplies encoded input and receives raw output bytes. Cached for up to two seconds. Returns 503 when no peer answers.
 */
export const queryContractMutation = (
  options?: Partial<Options<QueryContractData>>,
): UseMutationOptions<QueryContractResponse, DefaultError, Options<QueryContractData>> => {
  const mutationOptions: UseMutationOptions<
    QueryContractResponse,
    DefaultError,
    Options<QueryContractData>
  > = {
    mutationFn: async (fnOptions) => {
      const { data } = await queryContract({
        ...options,
        ...fnOptions,
        throwOnError: true,
      });
      return data;
    },
    mutationKey: queryContractMutationKey(options),
  };
  return mutationOptions;
};

