export const broadcastTransactionMutationKey = (
  options?: Partial<Options<BroadcastTransactionData>>,
) => createMutationKey("broadcastTransaction", options);

/**
 * Broadcast a signed transaction to direct peers
 *
 * Requires ALLOW_BROADCAST=true. The transaction is decoded and locally checked for amount range, input size, byte length, and SchnorrQ signature before any socket is opened. Valid transactions are fanned out concurrently to up to `peers` peers (capped by BROADCAST_PEERS). Set `dry_run` to run the same checks without broadcasting.
 *
 * Qubic does not acknowledge broadcasts. A `sent` peer means the packet reached the peer socket, not that the transaction will be included. Poll `meta.links.transaction`, or stream ticks, to observe inclusion.
 */
export const broadcastTransactionMutation = (
  options?: Partial<Options<BroadcastTransactionData>>,
): UseMutationOptions<
  BroadcastTransactionResponse,
  DefaultError,
  Options<BroadcastTransactionData>
> => {
  const mutationOptions: UseMutationOptions<
    BroadcastTransactionResponse,
    DefaultError,
    Options<BroadcastTransactionData>
  > = {
    mutationFn: async (fnOptions) => {
      const { data } = await broadcastTransaction({
        ...options,
        ...fnOptions,
        throwOnError: true,
      });
      return data;
    },
    mutationKey: broadcastTransactionMutationKey(options),
  };
  return mutationOptions;
};

